function getSessionSchedule(center) {
  const text = ((center.name || "") + " " + (center.conditions_text || "")).toLowerCase();
  if (text.includes("vipassana")) {
    return {
      pattern: "10-day silent courses, typically starting on the 1st and 15th of each month",
      note: "Vipassana centers following the Goenka tradition generally run fixed-length courses on a recurring monthly cycle. Registration usually required 1–2 weeks in advance.",
      cta: "Confirm exact upcoming dates directly with the center",
      images: [
        {img: SPIRITUAL_IMAGES[0], label: "Group Sitting &amp; Walking Practice"},
        {img: SPIRITUAL_IMAGES[2], label: "Silent Course Setting"}
      ]
    };
  }
  if (text.includes("forest monastery") || text.includes("aranya") || text.includes("hermitage")) {
    return {
      pattern: "Flexible-duration stays — no fixed intake dates",
      note: "Forest monasteries typically accept practitioners on a rolling basis rather than scheduled courses. Some require a formal request or referral before arrival.",
      cta: "Contact ahead to arrange your stay and confirm house rules",
      images: [
        {img: SPIRITUAL_IMAGES[0], label: "Forest Monastery Grounds"},
        {img: SPIRITUAL_IMAGES[1], label: "Quiet Reflection Point"}
      ]
    };
  }
  return {
    pattern: "Guided sessions typically offered weekly (often weekend mornings)",
    note: "General meditation centers commonly run shorter, drop-in-friendly sessions rather than multi-day residential courses.",
    cta: "Check with the center for this week's session times",
    images: [
      {img: SPIRITUAL_IMAGES[3], label: "Guided Group Session"},
      {img: SPIRITUAL_IMAGES[1], label: "Reflective Viewpoint"}
    ]
  };
}

function getSeasonalGuidance(district) {
  const d = (district || "").trim();
  if (EAST_NORTH_DISTRICTS.some(x => d.includes(x))) {
    return {
      bestTime: "May – September",
      note: "East/North coast: driest and calmest May–Sept (Yala season affects the opposite coast). Oct–Jan can bring the Maha monsoon here."
    };
  }
  if (HILL_DISTRICTS.some(x => d.includes(x))) {
    return {
      bestTime: "December – March",
      note: "Hill country: cooler year-round, driest Dec–Mar. Evenings can be chilly — pack a light jacket regardless of season."
    };
  }
  return {
    bestTime: "December – March",
    note: "West/South coast: driest and calmest Dec–Mar. May–Sept is the Yala monsoon season here — expect more rain."
  };
}

function getRatePerDay(priceTier) {
  const t = (priceTier || "").toLowerCase();
  if (t.includes("budget") && t.includes("mid")) return 12.5;
  if (t.includes("premium")) return 20;
  if (t.includes("budget")) return 10;
  return 15; // Mid / default
}

function parseDurationRange(rangeStr) {
  const nums = (rangeStr.match(/\d+/g) || []).map(Number);
  if (nums.length >= 2) return [nums[0], nums[1]];
  if (nums.length === 1) return [nums[0], nums[0]];
  return [null, null];
}

function getCostEstimate(condition, priceTier, travelers) {
  const d = getDurationInfo(condition);
  const [minDays, maxDays] = parseDurationRange(d.range);
  if (minDays === null) return null;
  const rate = getRatePerDay(priceTier);
  const minCost = Math.round(minDays * rate * travelers);
  const maxCost = Math.round(maxDays * rate * travelers);
  return {minCost, maxCost, minDays, maxDays, rate, travelers};
}

