// --- Voice input for the symptom text field (Web Speech API) ---
// HONEST LIMITATION: Web Speech API is well-supported in Chrome/Edge, but
// NOT in Firefox and has inconsistent support in Safari. Feature-detected
// below with a clear fallback message rather than a silent failure.
const SPEECH_LANG_MAP = { en: "en-US", de: "de-DE", ru: "ru-RU", zh: "zh-CN", ja: "ja-JP" };
window.VOICE_RECOGNITION = null;
window.VOICE_RECORDING = false;
window.VOICE_SPEAK_LANG = "en";  // explicitly chosen speaking language, defaults to English

function setVoiceLang(lang, btn) {
  window.VOICE_SPEAK_LANG = lang;
  document.querySelectorAll(".voice-lang-chip").forEach(c => c.classList.remove("active"));
  btn.classList.add("active");
}

// Script-based language detection on the TRANSCRIBED TEXT (not the audio
// itself - Web Speech API has no true "detect any spoken language"
// feature). Reliable for CJK/Cyrillic since they use distinct Unicode
// ranges. NOT reliable for German vs English (both Latin script) - that
// case is left as a documented limitation rather than guessed at.
function detectScriptLanguage(text) {
  if (/[\u3040-\u309F\u30A0-\u30FF]/.test(text)) return "ja";   // Hiragana/Katakana
  if (/[\u4E00-\u9FFF]/.test(text)) return "zh";                 // Han characters (no kana = likely Chinese, not Japanese)
  if (/[\u0400-\u04FF]/.test(text)) return "ru";                 // Cyrillic
  return null; // Latin-script result - can't reliably distinguish EN vs DE from script alone
}

function toggleVoiceInput() {
  const SpeechRecognitionAPI = window.SpeechRecognition || window.webkitSpeechRecognition;
  const micBtn = document.getElementById("micBtn");
  const resultEl = document.getElementById("symptomSuggestResult");

  if (!SpeechRecognitionAPI) {
    resultEl.innerHTML = `<span style="color:var(--orange);">${tr("Voice input isn't supported in this browser \u2014 try Chrome or Edge, or type instead.")}</span>`;
    return;
  }

  if (window.VOICE_RECORDING) {
    window.VOICE_RECOGNITION.stop();
    return;
  }

  const recognition = new SpeechRecognitionAPI();
  // Uses the EXPLICITLY chosen speaking language (the chip row), not the
  // current UI language - these can differ (e.g. UI in English, but the
  // tourist wants to speak Japanese to switch to it). Web Speech API needs
  // an accurate language hint BEFORE listening starts for good accuracy;
  // guessing from the current UI language caused poor transcription when
  // someone spoke a different language than whatever was last selected.
  recognition.lang = SPEECH_LANG_MAP[window.VOICE_SPEAK_LANG] || "en-US";
  recognition.interimResults = false;
  recognition.maxAlternatives = 1;

  recognition.onstart = () => {
    window.VOICE_RECORDING = true;
    micBtn.classList.add("recording");
    resultEl.innerHTML = `<span style="color:var(--muted);">${tr("Listening...")}</span>`;
  };

  recognition.onresult = (event) => {
    const transcript = event.results[0][0].transcript;
    document.getElementById("symptomText").value = transcript;
    resultEl.innerHTML = "";

    // Switch the UI to the language the user explicitly said they'd speak
    // in - guaranteed correct, not guessed. Script-detection is kept as a
    // secondary safety check in case the transcript's script clearly
    // contradicts the chosen chip (e.g. they forgot to change it).
    const targetLang = window.VOICE_SPEAK_LANG;
    if (targetLang !== window.CURRENT_LANG) {
      selectLanguage(targetLang);
      resultEl.innerHTML = `<span style="color:var(--teal);">${tr("Switched language based on your voice input.")}</span>`;
    } else {
      const detected = detectScriptLanguage(transcript);
      if (detected && detected !== window.CURRENT_LANG) {
        selectLanguage(detected);
        resultEl.innerHTML = `<span style="color:var(--teal);">${tr("Switched language based on your voice input.")}</span>`;
      }
    }
  };

  recognition.onerror = (event) => {
    let msg = tr("Could not hear you \u2014 please try again or type instead.");
    if (event.error === "not-allowed" || event.error === "permission-denied") {
      msg = tr("Microphone access denied \u2014 please allow microphone permission or type instead.");
    }
    resultEl.innerHTML = `<span style="color:var(--orange);">${msg}</span>`;
  };

  recognition.onend = () => {
    window.VOICE_RECORDING = false;
    micBtn.classList.remove("recording");
  };

  window.VOICE_RECOGNITION = recognition;
  recognition.start();
}

async function suggestConditionFromSymptom() {
  const text = document.getElementById("symptomText").value.trim();
  const resultEl = document.getElementById("symptomSuggestResult");
  if (!text) { resultEl.innerHTML = ""; return; }
  resultEl.innerHTML = `<span style="color:var(--muted);">${tr("Analyzing...")}</span>`;
  try {
    const res = await fetch("/api/classify-symptom", {
      method: "POST", headers: {"Content-Type": "application/json"},
      body: JSON.stringify({text, lang: window.VOICE_SPEAK_LANG || "en", domain: window.SELECTED_PATH || "ayurveda"})
    });
    const data = await res.json();
    if (data.no_signal) {
      resultEl.innerHTML = `<span style="color:var(--orange);">${tr("Couldn't match that to the selected language \u2014 check the 'Speaking in' chip matches what you typed/said, or use the dropdown instead.")}</span>`;
      return;
    }
    const select = document.getElementById("condition");
    const options = Array.from(select.options).map(o => o.value);
    if (options.includes(data.predicted_condition)) {
      select.value = data.predicted_condition;
    }
    const confPct = Math.round(data.confidence * 100);
    resultEl.innerHTML = `${tr("Suggested:")} <b>${data.predicted_condition}</b> (${confPct}% ${tr("confidence)")}
      <div style="color:var(--muted); font-size:0.72rem; margin-top:2px;">${tr("AI suggestion \u2014 please confirm using the dropdown.")}</div>`;
  } catch (err) {
    resultEl.innerHTML = `<span style="color:var(--orange);">${tr("Could not reach the server.")}</span>`;
  }
}

