// --- Safety / Risk Flag Detection (keyword-based, scans real embedded reviews) ---
const RISK_KEYWORDS = [
  "unhygienic", "unhygenic", "dirty", "unclean", "unsafe", "uncomfortable", "unprofessional",
  "vulnerable", "exposed", "avoid", "not recommend", "be careful", "beware", "warning",
  "rude", "scam", "overpriced", "inconsistent pricing", "inconsistent"
];

function detectRiskFlags(reviews) {
  if (!reviews || reviews.length === 0) return [];
  const flagged = [];
  reviews.forEach(text => {
    const lower = text.toLowerCase();
    const hit = RISK_KEYWORDS.find(k => lower.includes(k));
    if (hit) flagged.push(text);
  });
  return flagged;
}

