// NOTE: predictDosha() and matchCenters() below are now UNUSED by the main flow -
// runMatch() and runScenarioCompare() call the Python backend (/api/recommend,
// /api/match) instead, so results come from the real trained model + matching
// engine, not this JS copy. Left here only as historical/offline reference.
function predictDosha(sleep, appetite, sensitivity, emotion) {
  const votes = {Vata: 0, Pitta: 0, Kapha: 0};
  const traits = {sleep, appetite, sensitivity, emotion};
  for (const dosha of ["Vata","Pitta","Kapha"]) {
    for (const traitKey of ["sleep","appetite","sensitivity","emotion"]) {
      if (DOMINANT[dosha][traitKey].includes(traits[traitKey])) votes[dosha]++;
    }
  }
  let best = "Vata", bestVotes = -1;
  for (const d in votes) { if (votes[d] > bestVotes) { best = d; bestVotes = votes[d]; } }
  const confidence = Math.round((bestVotes / 4) * 100);
  return {dosha: best, confidence: Math.max(confidence, 40)};
}

function matchCenters(condition, dosha, budgetTier, topN=6, companionCondition=null) {
  const pathPool = getPathPool();
  const scored = pathPool.map(c => {
    const condMatch = c.conditions_text.toLowerCase().includes(condition.toLowerCase()) ? 1.0 : 0.3;
    let doshaMatch;
    if (c.dosha_focus === dosha) doshaMatch = 1.0;
    else if (c.dosha_focus === "General/Unspecified") doshaMatch = 0.6;
    else doshaMatch = 0.4;
    const quality = c.nlp_quality / 5.0;
    const budgetMatch = c.price_tier.includes(budgetTier) ? 1.0 : 0.5;
    const score = WEIGHTS.condition*condMatch + WEIGHTS.dosha*doshaMatch + WEIGHTS.quality*quality + WEIGHTS.budget*budgetMatch;

    let companionMatch = null;
    if (companionCondition) {
      companionMatch = c.conditions_text.toLowerCase().includes(companionCondition.toLowerCase()) ? 1.0 : 0.3;
    }

    return {
      name: c.name, category: c.category, price_tier: c.price_tier, quality_source: c.quality_source,
      phone: c.phone, lat: c.lat, lng: c.lng, reviews: c.reviews || [], conditions_text: c.conditions_text,
      nlp_quality: c.nlp_quality, queried_condition: condition,
      verified: c.verified, notes: c.notes, address: c.address, district: c.district,
      google_rating_real: c.google_rating_real, review_count_real: c.review_count_real,
      match_pct: Math.round(score*100),
      condition_pct: Math.round(condMatch*WEIGHTS.condition*100),
      dosha_pct: Math.round(doshaMatch*WEIGHTS.dosha*100),
      quality_pct: Math.round(quality*WEIGHTS.quality*100),
      budget_pct: Math.round(budgetMatch*WEIGHTS.budget*100),
      companion_condition: companionCondition,
      companion_match: companionMatch,
      combined_pct: companionMatch !== null ? Math.round((0.65*score + 0.35*companionMatch)*100) : Math.round(score*100),
    };
  });
  // If traveling with a companion, prioritize centers that serve BOTH conditions well
  scored.sort((a,b) => companionCondition ? (b.combined_pct - a.combined_pct) : (b.match_pct - a.match_pct));
  return scored.slice(0, topN);
}

function bar(label, val, max) {
  const pct = Math.round((val/max)*100);
  return `<div class="score-bar-row"><span class="score-label">${label}</span>
    <div class="score-track"><div class="score-fill" style="width:${pct}%"></div></div>
    <span class="score-val">${val}</span></div>`;
}

function renderResults(dosha, confidence, results) {
  document.body.classList.remove("step-mode");
  window.CURRENT_RESULTS = results;

  let html = window.SELECTED_PATH === "spiritual"
    ? `<div class="dosha-banner"><div class="dosha-name">Matched by retreat type, quality &amp; budget</div></div>`
    : `<div class="dosha-banner"><div class="dosha-name">Predicted Dosha: ${dosha}</div>
    <div class="conf">${confidence}% confidence</div></div>`;
  html += `
    <div style="display:flex; gap:10px; flex-wrap:wrap; margin-bottom:18px;">
      <button class="compare-toggle-btn" onclick="toggleCompare()">&#9878; Compare Top 3 Matches</button>
      <button class="compare-toggle-btn" onclick="showMapView()">&#128506; View All on Map</button>
      <button class="compare-toggle-btn" onclick="showScenarioView()">&#128260; Try a Different Scenario</button>
    </div>
    <div id="compareTable" style="display:none;"></div>
    <div class="results-grid">`;

  results.forEach((r, i) => {
    const idx = i;
    html += `<div class="result-card"><div class="rank">MATCH #${i+1}</div>
      <h3><span class="cat-badge">${CATEGORY_ICON[r.category] || "&#127807;"}</span>${r.name}</h3>
      <div class="meta">${r.category} &middot; ${r.price_tier} tier &middot; ${tr(r.quality_source)}</div>
      ${detectRiskFlags(r.reviews).length > 0 ? `<div class="risk-badge">&#9888; Reviewer caution noted &mdash; see details</div>` : ``}
      ${r.companion_match === 1.0 ? `<div class="companion-badge">&#128101; Also matches your companion's condition</div>` : ``}
      ${bar("Condition match", r.condition_pct, 35)}
      ${r.dosha_pct !== null ? bar("Dosha compatibility", r.dosha_pct, 20) : ``}
      ${bar("Review quality", r.quality_pct, 25)}
      ${bar("Budget fit", r.budget_pct, 20)}
      <div class="total-match">Overall Match: ${r.match_pct}%</div>
      <div class="contact-row">
        ${r.phone ? `<a class="contact-btn book-btn" href="tel:${r.phone.replace(/\s/g,'')}">&#128222; ${tr("Book Now")} &middot; ${r.phone}</a>` : `<span class="contact-btn disabled">${tr("Phone not listed \u2014 use map to find contact")}</span>`}
        ${r.lat && r.lng ? `<a class="contact-btn map-btn" href="https://www.google.com/maps?q=${r.lat},${r.lng}" target="_blank">&#128205; ${tr("View on Map")}</a>` : ``}
      </div>
      <button class="detail-btn" onclick="showDetail(${idx})">${tr("View Full Details")} &rarr;</button>
    </div>`;
  });
  html += `</div><button class="restart-btn" onclick="restart()">&larr; Start Over</button>`;

  document.getElementById("formView").style.display = "none";
  document.getElementById("detailView").style.display = "none";
  document.getElementById("browseView").style.display = "none";
  document.getElementById("mapView").style.display = "none";
  document.getElementById("costView").style.display = "none";
  document.getElementById("languageView").style.display = "none";
  document.getElementById("scenarioView").style.display = "none";
  const rv = document.getElementById("resultsWrap");
  rv.innerHTML = html;
  rv.style.display = "block";
  window.scrollTo({top:0, behavior:"smooth"});
}

async function runMatch() {
  const condition = document.getElementById("condition").value;
  const age = parseInt(document.getElementById("age").value) || 45;
  const gender = document.getElementById("gender").value;
  const sleep = window.QUIZ_STATE.sleep;
  const appetite = window.QUIZ_STATE.appetite;
  const sensitivity = window.QUIZ_STATE.sensitivity;
  const emotion = window.QUIZ_STATE.emotion;
  const budget = document.getElementById("budget").value;
  const companionCondition = window.HAS_COMPANION ? document.getElementById("companionCondition").value : null;

  const btn = document.getElementById("findMatchBtn");
  const originalBtnText = btn.textContent;
  btn.textContent = "Finding your match...";
  btn.disabled = true;

  let dosha, confidence, results;
  try {
    const response = await fetch("/api/recommend", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({
        condition, age, gender,
        sleep_pattern: sleep, appetite,
        cold_heat_sensitivity: sensitivity, emotional_tendency: emotion,
        budget_tier: budget, top_n: 6,
        companion_condition: companionCondition,
        path: window.SELECTED_PATH
      })
    });
    if (!response.ok) throw new Error("Server returned " + response.status);
    const data = await response.json();
    dosha = data.predicted_dosha;
    confidence = data.dosha_confidence_pct;
    results = data.recommendations;
  } catch (err) {
    btn.textContent = originalBtnText;
    btn.disabled = false;
    alert("Could not reach the matching server. Make sure the backend (app.py) is running, then try again.\n\n(" + err.message + ")");
    return;
  }

  btn.textContent = originalBtnText;
  btn.disabled = false;

  window.LAST_QUERY = {condition, dosha, confidence, budget, companionCondition, path: window.SELECTED_PATH, age};
  renderResults(dosha, confidence, results);
  history.pushState({type:"results", dosha, confidence, results}, "", "");
}

function restart() {
  document.getElementById("resultsWrap").style.display = "none";
  document.getElementById("detailView").style.display = "none";
  document.getElementById("browseView").style.display = "none";
  document.getElementById("formView").style.display = "block";
  backToPathSelect();
  history.pushState({type:"path"}, "", "");
  window.scrollTo({top:0, behavior:"smooth"});
}

