window.CURRENT_LANG = "en";

function applyTranslations(lang) {
  window.CURRENT_LANG = lang;
  const t = TRANSLATIONS[lang];
  const navLinks = document.querySelectorAll(".nav-links > a");
  if (navLinks[1]) navLinks[1].innerHTML = t.navMap;
  const label = document.getElementById("currentLangLabel");
  if (label) label.textContent = lang.toUpperCase();
  const symptomInput = document.getElementById("symptomText");
  if (symptomInput && window.CURRENT_PATH_CONTENT) {
    symptomInput.placeholder = tr(window.CURRENT_PATH_CONTENT.symptomPlaceholder);
  }
  // Keep the voice speaking-language chip row in sync with the UI language
  // switch (e.g. via the nav dropdown) so the two selectors never disagree.
  window.VOICE_SPEAK_LANG = lang;
  const chip = document.querySelector(`.voice-lang-chip[data-lang="${lang}"]`);
  if (chip) {
    document.querySelectorAll(".voice-lang-chip").forEach(c => c.classList.remove("active"));
    chip.classList.add("active");
  }
  translateVisibleText(lang);
}

function translateVisibleText(lang) {
  if (lang === "en") return; // English is the source language, nothing to replace
  const dict = {};
  for (const [en, translations] of Object.entries(PHRASE_DICTIONARY)) {
    if (translations[lang]) dict[en] = translations[lang];
  }
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, {
    acceptNode: (node) => {
      const parentTag = node.parentElement ? node.parentElement.tagName : "";
      if (parentTag === "SCRIPT" || parentTag === "STYLE") return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    }
  });
  const nodes = [];
  let n;
  while ((n = walker.nextNode())) nodes.push(n);
  nodes.forEach(node => {
    const trimmed = node.nodeValue.trim();
    if (dict[trimmed]) {
      node.nodeValue = node.nodeValue.replace(trimmed, dict[trimmed]);
    }
  });
}

function toggleLangDropdown(evt) {
  evt.stopPropagation();
  const dropdown = document.getElementById("langDropdown");
  dropdown.style.display = dropdown.style.display === "block" ? "none" : "block";
}
document.addEventListener("click", () => {
  const dropdown = document.getElementById("langDropdown");
  if (dropdown) dropdown.style.display = "none";
});

// Auto re-translate whenever the page content changes (view switches,
// results render, detail page loads, etc.) - avoids having to manually
// hook every render*() function individually across the codebase.
const _langObserver = new MutationObserver(() => {
  if (window.CURRENT_LANG && window.CURRENT_LANG !== "en") {
    translateVisibleText(window.CURRENT_LANG);
  }
});
window.addEventListener("DOMContentLoaded", () => {
  _langObserver.observe(document.body, {childList: true, subtree: true});
});
// In case this script runs after DOMContentLoaded already fired:
if (document.readyState !== "loading") {
  _langObserver.observe(document.body, {childList: true, subtree: true});
}

function renderScenarioView() {
  document.getElementById("formView").style.display = "none";
  document.getElementById("resultsWrap").style.display = "none";
  document.getElementById("detailView").style.display = "none";
  document.getElementById("browseView").style.display = "none";
  document.getElementById("mapView").style.display = "none";
  document.getElementById("costView").style.display = "none";
  document.getElementById("languageView").style.display = "none";
  const sv = document.getElementById("scenarioView");
  sv.style.display = "block";

  const q = window.LAST_QUERY;
  if (!q) {
    sv.innerHTML = `<span class="back-link" onclick="history.back()">&larr; ${tr("Back")}</span><div class="no-results">${tr("Run a search first, then come back to compare scenarios.")}</div>`;
    window.scrollTo({top:0, behavior:"smooth"});
    return;
  }

  const budgetOptions = ["Budget", "Mid", "Premium"].map(b =>
    `<option ${b === q.budget ? "selected" : ""}>${b}</option>`).join("");
  const conditionOptions = CONDITIONS_BY_PATH[q.path || "ayurveda"].map(c =>
    `<option ${c === q.condition ? "selected" : ""}>${c}</option>`).join("");

  sv.innerHTML = `
    <span class="back-link" onclick="history.back()">&larr; ${tr("Back")}</span>
    <div class="leaf-divider">${LEAF_SVG}<span style="font-size:0.78rem; font-weight:600; letter-spacing:0.05em; text-transform:uppercase;">${tr("What If")}</span>${LEAF_SVG}</div>
    <div class="browse-header"><h2>Try a Different Scenario</h2><p>Keep your wellness profile, tweak your trip details, and see how your matches change.</p></div>
    <div class="panel" style="margin-bottom:24px;">
      <div class="field"><label>Condition / reason for visit</label>
        <select id="scenarioCondition">${conditionOptions}</select>
      </div>
      <div class="field"><label>Budget tier</label>
        <select id="scenarioBudget">${budgetOptions}</select>
      </div>
      <div class="btn-row"><button class="primary" onclick="runScenarioCompare()">Compare Scenarios</button></div>
    </div>
    <div id="scenarioResults"></div>
  `;
  translateVisibleText(window.CURRENT_LANG);
  window.scrollTo({top:0, behavior:"smooth"});
}

function showScenarioView() {
  renderScenarioView();
  history.pushState({type:"scenario"}, "", "");
}

async function runScenarioCompare() {
  const q = window.LAST_QUERY;
  const newCondition = document.getElementById("scenarioCondition").value;
  const newBudget = document.getElementById("scenarioBudget").value;
  const resultsBox = document.getElementById("scenarioResults");
  resultsBox.innerHTML = `<div class="no-results">Comparing...</div>`;

  let a, b;
  try {
    const [respA, respB] = await Promise.all([
      fetch("/api/match", {
        method: "POST", headers: {"Content-Type": "application/json"},
        body: JSON.stringify({condition: q.condition, dosha: q.dosha, budget_tier: q.budget,
                                companion_condition: q.companionCondition, path: q.path, top_n: 1})
      }),
      fetch("/api/match", {
        method: "POST", headers: {"Content-Type": "application/json"},
        body: JSON.stringify({condition: newCondition, dosha: q.dosha, budget_tier: newBudget,
                                companion_condition: q.companionCondition, path: q.path, top_n: 1})
      })
    ]);
    if (!respA.ok || !respB.ok) throw new Error("Server error");
    const dataA = await respA.json();
    const dataB = await respB.json();
    a = dataA.recommendations[0];
    b = dataB.recommendations[0];
  } catch (err) {
    resultsBox.innerHTML = `<div class="no-results">Could not reach the matching server. Make sure the backend is running.</div>`;
    return;
  }

  const rows = [
    {label: "Condition", a: q.condition, b: newCondition},
    {label: "Budget Tier", a: q.budget, b: newBudget},
    {label: "Top Match", a: a.name, b: b.name},
    {label: "Overall Match", a: a.match_pct + "%", b: b.match_pct + "%"},
    {label: "Review Quality", a: a.nlp_quality + "/5", b: b.nlp_quality + "/5"},
    {label: "Price Tier", a: a.price_tier, b: b.price_tier},
  ];

  let html = `<table class="compare-table"><thead><tr><th></th><th>Scenario A (Original)</th><th>Scenario B (New)</th></tr></thead><tbody>`;
  rows.forEach(r => {
    const diff = r.a !== r.b;
    html += `<tr><td class="metric-label">${r.label}</td><td class="${diff ? 'best-score' : ''}">${r.a}</td><td class="${diff ? 'best-score' : ''}">${r.b}</td></tr>`;
  });
  html += `</tbody></table>`;

  resultsBox.innerHTML = html;
}

