function shareMatch(name, matchPct, phone) {
  const text = `I found this Ayurveda/wellness center via Tour Ceylon: ${name}` +
    (matchPct ? ` (${matchPct}% match for my profile)` : "") +
    (phone ? ` — Contact: ${phone}` : "") +
    ` — shared from Tour Ceylon Wellness Matcher.`;
  const encoded = encodeURIComponent(text);
  const waUrl = `https://wa.me/?text=${encoded}`;
  const mailUrl = `mailto:?subject=${encodeURIComponent("Ayurveda center: " + name)}&body=${encoded}`;

  const choice = confirm("Share via WhatsApp? (Cancel for Email instead)");
  window.open(choice ? waUrl : mailUrl, "_blank");
}

// --- Currency conversion (static rates, illustrative) ---
const CURRENCY_RATES = {
  USD: {symbol: "$", rate: 1},
  EUR: {symbol: "€", rate: 0.92},
  GBP: {symbol: "£", rate: 0.79},
  RUB: {symbol: "₽", rate: 92.5},
};
window.CURRENT_CURRENCY = "USD";

function convertCurrency(usdAmount, currency) {
  const c = CURRENCY_RATES[currency] || CURRENCY_RATES.USD;
  return c.symbol + Math.round(usdAmount * c.rate).toLocaleString();
}

function renderCostView(idx) {
  document.getElementById("formView").style.display = "none";
  document.getElementById("resultsWrap").style.display = "none";
  document.getElementById("detailView").style.display = "none";
  document.getElementById("browseView").style.display = "none";
  document.getElementById("mapView").style.display = "none";
  document.getElementById("languageView").style.display = "none";
  document.getElementById("scenarioView").style.display = "none";
  const cv = document.getElementById("costView");
  cv.style.display = "block";

  const r = window.CURRENT_RESULTS[idx];
  const travelers = (r.companion_condition) ? 2 : 1;
  const est = getCostEstimate(r.queried_condition, r.price_tier, travelers);

  window.CURRENT_COST_IDX = idx;
  let html = `<span class="back-link" onclick="history.back()">&larr; ${tr("Back")}</span>`;
  if (!est) {
    html += `<div class="no-results">Cost estimate not available for this condition yet.</div>`;
  } else {
    const cur = window.CURRENT_CURRENCY;
    html += `
      <div class="currency-selector">
        ${Object.keys(CURRENCY_RATES).map(c => `<button class="currency-btn ${c===cur?'active':''}" onclick="changeCostCurrency('${c}')">${c}</button>`).join("")}
      </div>
      <div class="cost-hero">
        <div style="font-size:0.8rem; opacity:0.85; text-transform:uppercase; letter-spacing:0.05em;">Estimated Trip Cost</div>
        <div class="cost-figure">${convertCurrency(est.minCost, cur)} &ndash; ${convertCurrency(est.maxCost, cur)}</div>
        <div style="font-size:0.85rem; opacity:0.85;">${r.name}</div>
      </div>
      <div class="detail-card">
        <h4>Cost Breakdown</h4>
        <div class="cost-breakdown-row"><span class="label">Estimated duration</span><span class="val">${est.minDays}&ndash;${est.maxDays} days</span></div>
        <div class="cost-breakdown-row"><span class="label">Rate (${r.price_tier})</span><span class="val">~${convertCurrency(est.rate, cur)} / day / person</span></div>
        <div class="cost-breakdown-row"><span class="label">Travelers</span><span class="val">${est.travelers} ${est.travelers > 1 ? "(with companion)" : ""}</span></div>
        <div class="cost-breakdown-row"><span class="label">Total estimate</span><span class="val">${convertCurrency(est.minCost, cur)} &ndash; ${convertCurrency(est.maxCost, cur)}</span></div>
      </div>
      <div class="browse-note">Estimate only, based on domain-expert-informed duration data and Ayya's price-tier reference ($10/$15/$20 per day). Exchange rates are static/illustrative. Excludes flights, transport, and incidentals. Confirm actual pricing directly with the center.</div>
    `;
  }

  cv.innerHTML = html;
  translateVisibleText(window.CURRENT_LANG);
  window.scrollTo({top:0, behavior:"smooth"});
}

function changeCostCurrency(currency) {
  window.CURRENT_CURRENCY = currency;
  renderCostView(window.CURRENT_COST_IDX);
}

function showCostView(idx) {
  renderCostView(idx);
  history.pushState({type:"cost", idx}, "", "");
}

