let carouselIdx = 0;
let carouselTimer = null;

function initCarousel() {
  carouselIdx = 0;
  const track = document.getElementById("carouselTrack");
  if (!track) return;
  const carouselImgs = window.CURRENT_DETAIL_CATEGORY === "Spiritual/Meditation" ? SPIRITUAL_IMAGES : SPA_IMAGES;
  track.innerHTML = carouselImgs.map(src => `<img src="${src}">`).join("");
  const n = track.children.length;
  const dotsEl = document.getElementById("carouselDots");
  dotsEl.innerHTML = "";
  for (let i=0; i<n; i++) {
    const dot = document.createElement("span");
    if (i===0) dot.className = "active";
    dot.onclick = () => { carouselGoto(i); };
    dotsEl.appendChild(dot);
  }
  updateCarousel();
  if (carouselTimer) clearInterval(carouselTimer);
  carouselTimer = setInterval(() => carouselMove(1), 4000);
}

function updateCarousel() {
  const track = document.getElementById("carouselTrack");
  if (!track) return;
  track.style.transform = `translateX(-${carouselIdx * 100}%)`;
  const dots = document.querySelectorAll("#carouselDots span");
  dots.forEach((d, i) => d.classList.toggle("active", i === carouselIdx));
}

function carouselMove(dir) {
  const track = document.getElementById("carouselTrack");
  if (!track) return;
  const n = track.children.length;
  carouselIdx = (carouselIdx + dir + n) % n;
  updateCarousel();
}

function carouselGoto(i) {
  carouselIdx = i;
  updateCarousel();
}

function showDetail(idx, push=true) {
  renderDetail(idx);
  loadPersonalizedOutcome(idx);
  loadSafetyCheck(idx);
  translateVisibleText(window.CURRENT_LANG);
  if (push) history.pushState({type:"detail", idx, results: window.CURRENT_RESULTS}, "", "");
}

async function loadSafetyCheck(idx) {
  const r = window.CURRENT_RESULTS[idx];
  const placeholder = document.getElementById("safetyCard-placeholder");
  if (!placeholder || !r.reviews || r.reviews.length === 0) return;

  try {
    const res = await fetch("/api/safety-check", {
      method: "POST", headers: {"Content-Type": "application/json"},
      body: JSON.stringify({reviews: r.reviews})
    });
    const data = await res.json();
    const flags = data.flags || [];
    if (flags.length === 0) { placeholder.innerHTML = ""; return; }

    placeholder.innerHTML = `<div class="risk-card">
      <h4>&#9888; Reviewer Caution</h4>
      ${flags.map(f => {
        const agree = f.flagged_by_keyword && f.flagged_by_ml_model;
        const badge = agree
          ? `<span style="color:var(--herb); font-size:0.7rem; font-weight:700;">&#10003; Keyword + ML agree</span>`
          : f.flagged_by_keyword
            ? `<span style="color:var(--muted); font-size:0.7rem;">Keyword only (ML: ${Math.round((f.ml_confidence||0)*100)}% concern) &mdash; possible false positive</span>`
            : `<span style="color:var(--orange); font-size:0.7rem;">ML model only (${Math.round((f.ml_confidence||0)*100)}% concern)</span>`;
        return `<div class="risk-review">"${f.text}"<div style="margin-top:4px;">${badge}</div></div>`;
      }).join("")}
      <div class="risk-note">Cross-checked using both keyword matching and a trained ML classifier for transparency. Read in context before deciding.</div>
    </div>`;
  } catch (err) {
    // Silent fail - static keyword-only card (already rendered) remains as fallback.
  }
}

async function loadPersonalizedOutcome(idx) {
  const r = window.CURRENT_RESULTS[idx];
  const q = window.LAST_QUERY;
  const card = document.getElementById("outcomeCard-" + idx);
  if (!card || !r.queried_condition || !q || !q.age) return;

  try {
    const res = await fetch("/api/predict-outcome", {
      method: "POST", headers: {"Content-Type": "application/json"},
      body: JSON.stringify({age: q.age, dosha: q.dosha, condition: r.queried_condition, duration_days: 21})
    });
    const data = await res.json();
    if (data.personalized) {
      card.innerHTML = `
        <h4>${tr("Personalized Outcome Likelihood")}</h4>
        <div style="font-size:1.4rem; font-weight:700; color:var(--orange);">~${data.predicted_outcome_pct}%</div>
        <div style="font-size:0.76rem; color:var(--muted); margin-top:6px;">${tr("Personalized for your profile (age")} ${q.age}, ${q.dosha} ${tr("dosha)")}</div>
        <div style="font-size:0.7rem; color:var(--muted); margin-top:8px; font-style:italic;">${data.basis}. ${tr("Model accuracy:")} ${data.model_accuracy}. ${tr("Not a clinical guarantee.")}</div>
      `;
    }
    // If not personalized (condition outside training anchors), the static card already shown stays as-is.
  } catch (err) {
    // Silent fail - static card (already rendered) remains as a reasonable fallback.
  }
}

function hideDetail() {
  history.back();
}

function renderBrowse(query, categoryFilter) {
  categoryFilter = categoryFilter || window.BROWSE_CATEGORY || "all";
  window.BROWSE_CATEGORY = categoryFilter;
  document.getElementById("formView").style.display = "none";
  document.getElementById("resultsWrap").style.display = "none";
  document.getElementById("detailView").style.display = "none";
  document.getElementById("mapView").style.display = "none";
  document.getElementById("costView").style.display = "none";
  document.getElementById("languageView").style.display = "none";
  document.getElementById("scenarioView").style.display = "none";
  const bv = document.getElementById("browseView");
  bv.style.display = "block";

  const q = (query || "").toLowerCase().trim();
  let pool = POOL;
  if (categoryFilter === "ayurveda") pool = POOL.filter(c => c.category !== "Spiritual/Meditation");
  else if (categoryFilter === "spiritual") pool = POOL.filter(c => c.category === "Spiritual/Meditation");
  const filtered = pool.filter(c => c.name.toLowerCase().includes(q) || c.conditions_text.toLowerCase().includes(q));

  let itemsHtml = "";
  if (filtered.length === 0) {
    itemsHtml = `<div class="no-results">No centers match "${query}". Try a different name or keyword.</div>`;
  } else {
    filtered.forEach(c => {
      const poolIdx = POOL.indexOf(c);
      itemsHtml += `<div class="browse-item" onclick="showBrowseDetail(${poolIdx})">
        <div class="browse-item-info">
          <h4>${c.name}</h4>
          <div class="meta">${c.category} &middot; ${c.price_tier} tier &middot; ${c.conditions_text}</div>
        </div>
        <div class="browse-item-rating">&#9733; ${c.nlp_quality}/5</div>
      </div>`;
    });
  }

  bv.innerHTML = `
    <span class="back-link" onclick="history.back()">&larr; ${tr("Back")}</span>
    <div class="leaf-divider"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M4 20 C4 12 9 6 20 4 C18 15 12 20 4 20 Z"/><path d="M4 20 C9 15 13 11 18 6"/></svg><span style="font-size:0.78rem; font-weight:600; letter-spacing:0.05em; text-transform:uppercase;">${tr("Direct Search")}</span><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M4 20 C4 12 9 6 20 4 C18 15 12 20 4 20 Z"/><path d="M4 20 C9 15 13 11 18 6"/></svg></div>
    <div class="browse-header">
      <h2>${tr("Browse All Centers")}</h2>
      <p>${tr("Already know where you want to go? Search directly \u2014 no profile matching needed.")}</p>
    </div>
    <div class="browse-note">${tr("Returning for treatment at a specific center, or recommended one by a friend? Find it here and go straight to contact details \u2014 this skips the personalized matching questions.")}</div>
    <div class="browse-tabs">
      <button class="browse-tab ${categoryFilter==='all'?'active':''}" onclick="filterBrowse(document.getElementById('browseSearch').value, 'all')">${tr("All")} (${POOL.length})</button>
      <button class="browse-tab ${categoryFilter==='ayurveda'?'active':''}" onclick="filterBrowse(document.getElementById('browseSearch').value, 'ayurveda')">&#127807; ${tr("Ayurveda Wellness")} (${POOL.filter(c=>c.category!=='Spiritual/Meditation').length})</button>
      <button class="browse-tab ${categoryFilter==='spiritual'?'active':''}" onclick="filterBrowse(document.getElementById('browseSearch').value, 'spiritual')">&#128330; ${tr("Meditation & Spiritual")} (${POOL.filter(c=>c.category==='Spiritual/Meditation').length})</button>
    </div>
    <input type="text" class="search-box" id="browseSearch" placeholder="${tr("Search by name or condition (e.g. 'Ayu Care', 'Negombo', 'Sciatica')...")}" value="${query || ''}" oninput="filterBrowse(this.value)">
    <div class="browse-list">${itemsHtml}</div>
  `;
  document.getElementById("browseSearch").focus();
  translateVisibleText(window.CURRENT_LANG);
  window.scrollTo({top:0, behavior:"smooth"});
}

function filterBrowse(query, category) {
  renderBrowse(query, category);
  const input = document.getElementById("browseSearch");
  input.focus();
  input.setSelectionRange(input.value.length, input.value.length);
  history.replaceState({type:"browse", query, category: window.BROWSE_CATEGORY}, "", "");
}

function goBrowse() {
  window.BROWSE_CATEGORY = "all";
  renderBrowse("", "all");
  history.pushState({type:"browse", query:"", category:"all"}, "", "");
}

function showBrowseDetail(poolIdx) {
  const c = POOL[poolIdx];
  // Build a detail-compatible object (no match_pct/breakdown - browse mode)
  window.CURRENT_RESULTS = [{
    name: c.name, category: c.category, price_tier: c.price_tier, conditions_text: c.conditions_text,
    phone: c.phone, lat: c.lat, lng: c.lng, reviews: c.reviews || [], nlp_quality: c.nlp_quality,
    quality_source: c.quality_source, verified: c.verified, notes: c.notes, address: c.address,
    district: c.district, google_rating_real: c.google_rating_real, review_count_real: c.review_count_real
  }];
  renderDetail(0);
  loadSafetyCheck(0);
  history.pushState({type:"browseDetail", poolIdx}, "", "");
}

// NOTE: hero used to have its own separate photo rotation (heroBgLayer),
// running out-of-sync with the page-level background - this caused a visible
// seam where the two independently-rotating photos met. Consolidated to a
// single continuous background (#pageBgLayer, see startPageBackground()) that
// spans the whole page seamlessly, with the hero's own darker overlay
// (.hero-overlay) layered on top just for extra text contrast in that zone.
startPageBackground(ALL_IMAGES);

// --- Browser/device back-button support ---
history.replaceState({type:"path"}, "", "");

window.addEventListener("popstate", function(e) {
  const state = e.state || {type:"path"};
  if (state.type === "path") {
    document.getElementById("resultsWrap").style.display = "none";
    document.getElementById("detailView").style.display = "none";
    document.getElementById("browseView").style.display = "none";
    document.getElementById("formView").style.display = "block";
    backToPathSelect();
  } else if (state.type === "step") {
    if (state.path) { window.SELECTED_PATH = state.path; populateConditionSelect(); }
    document.getElementById("pathSelect").style.display = "none";
    document.getElementById("progressWrap").style.display = "flex";
    document.getElementById("wizardPanel").style.display = "block";
    renderStep(state.step);
  } else if (state.type === "results") {
    renderResults(state.dosha, state.confidence, state.results);
  } else if (state.type === "detail") {
    window.CURRENT_RESULTS = state.results;
    renderDetail(state.idx);
    loadPersonalizedOutcome(state.idx);
    loadSafetyCheck(state.idx);
  } else if (state.type === "browse") {
    renderBrowse(state.query, state.category);
  } else if (state.type === "map") {
    renderMapView();
  } else if (state.type === "cost") {
    renderCostView(state.idx);
  } else if (state.type === "language") {
    renderLanguageView();
  } else if (state.type === "scenario") {
    renderScenarioView();
  } else if (state.type === "browseDetail") {
    const c = POOL[state.poolIdx];
    window.CURRENT_RESULTS = [{
      name: c.name, category: c.category, price_tier: c.price_tier, conditions_text: c.conditions_text,
      phone: c.phone, lat: c.lat, lng: c.lng, reviews: c.reviews || [], nlp_quality: c.nlp_quality,
      quality_source: c.quality_source, verified: c.verified, notes: c.notes, address: c.address,
      district: c.district, google_rating_real: c.google_rating_real, review_count_real: c.review_count_real
    }];
    renderDetail(0);
    loadSafetyCheck(0);
  }
});
